    if (isScramble(s1.slice(0, k), s2.slice(0, k)) && isScramble(s1.slice(k), s2.slice(k))) return true;
    if (isScramble(s1.slice(0, k), s2.slice(n - k)) && isScramble(s1.slice(k), s2.slice(0, n - k))) return true;
  }
  return false;
}

